impl RenderOnce for Input {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let core = InputCore {
            label: self.label,
            disabled: self.disabled,
            read_only: self.read_only,
            invalid: self.invalid,
            bordered: self.bordered,
            paste_handler: self.paste_handler,
        };
        let root = core
            .render("input", self.state, &theme, window, cx)
            .h(theme.space(8.))
            .items_center();
        super::theme::apply_style(root, &self.style)
    }
}

impl RenderOnce for Textarea {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let core = InputCore {
            label: self.label,
            disabled: self.disabled,
            read_only: self.read_only,
            invalid: self.invalid,
            bordered: self.bordered,
            paste_handler: self.paste_handler,
        };
        let input = self.state.clone();
        let root = core
            .render("textarea", self.state, &theme, window, cx)
            .min_h(theme.space(16.))
            .items_start()
            .py(theme.space(2.));
        let editable = !self.disabled && !self.read_only;
        let root = match self.misspellings {
            Some(misspellings) => {
                install_spelling_menu(&input, &misspellings, editable, cx);
                let replacer = misspellings.clone();
                root.relative()
                    .when(editable, |root| {
                        root.on_action(move |action: &ReplaceMisspelling, window, cx| {
                            replacer.update(cx, |misspellings, cx| {
                                misspellings.replace(
                                    action.range.clone(),
                                    action.text.clone(),
                                    window,
                                    cx,
                                )
                            });
                        })
                    })
                    .child(misspelling_underlines(input, misspellings, &theme))
            }
            None => root,
        };
        super::theme::apply_style(root, &self.style)
    }
}

/// Shows the spelling items and the edit items on a right-click.
fn install_spelling_menu(
    input: &Entity<TextareaState>,
    misspellings: &Entity<Misspellings>,
    editable: bool,
    cx: &mut App,
) {
    let misspellings = misspellings.downgrade();
    let weak_input = input.downgrade();
    input.update(cx, |state, _| {
        state.on_context_menu(Rc::new(move |_, capabilities, position, window, cx| {
            let (Some(input), Some(misspellings)) = (weak_input.upgrade(), misspellings.upgrade())
            else {
                return;
            };
            // The right-click has already moved the caret to the word.
            let (cursor, value) = {
                let input = input.read(cx);
                (input.cursor(), input.value())
            };
            let found = misspellings.read(cx).range_at(cursor);
            let handler = misspellings.read(cx).menu.clone();
            let mut menu = NativeMenu::new();
            if let (Some(range), Some(handler), true) = (found, handler, editable) {
                let mut spelling = SpellingMenu {
                    word: value
                        .get(range.clone())
                        .unwrap_or_default()
                        .to_string()
                        .into(),
                    range,
                    menu,
                };
                handler(&mut spelling, window, cx);
                menu = spelling.menu;
            }
            edit_menu(
                menu,
                capabilities.is_copyable(),
                editable && !capabilities.is_readonly(),
            )
            .show(position, window, cx);
        }));
    });
}

/// The Nova editing frame around any Kit input state. `Input` and `Textarea`
/// differ only in their size, so both build on this.
#[doc(hidden)]
pub struct InputCore {
    pub label: Option<SharedString>,
    pub disabled: bool,
    pub read_only: bool,
    pub invalid: bool,
    pub bordered: bool,
    pub paste_handler: Option<PasteHandler>,
}

impl InputCore {
    /// The editor colors every Kit input in a gpuicn app uses.
    pub fn editor_style(theme: &UiTheme) -> InputEditorStyle {
        let colors = theme.colors;
        InputEditorStyle {
            foreground: colors.foreground.into(),
            muted_foreground: colors.muted_foreground.into(),
            background: colors.background.into(),
            border: colors.input.into(),
            selection: colors.ring.opacity(0.3).into(),
            caret: colors.foreground.into(),
            ..Default::default()
        }
    }

    #[doc(hidden)]
    pub fn render<M: InputModeKind>(
        self,
        kind: &'static str,
        state: Entity<InputBaseState<M>>,
        theme: &UiTheme,
        window: &mut Window,
        cx: &mut App,
    ) -> InputBase {
        let editor_style = Self::editor_style(theme);
        state.update(cx, |state, cx| {
            state.set_disabled(self.disabled, cx);
            state.set_readonly(self.read_only, cx);
            state.set_editor_style(editor_style);
        });
        let read = state.read(cx);
        let focus_handle = read.focus_handle(cx);
        let focused = focus_handle.is_focused(window) && !self.disabled;
        let value = read.value();
        let placeholder = read.presentation().placeholder().clone();
        let action_state = state.clone();
        let click_state = state.clone();
        let a11y_focus = state.clone();
        let paste_handler = self
            .paste_handler
            .filter(|_| !self.disabled && !self.read_only);
        let root = InputBase::new(ElementId::from((kind, state.entity_id())))
            .focused(focused)
            .disabled(self.disabled)
            .when_some(self.label, |root, label| root.accessibility_label(label))
            .aria_value(value)
            .aria_placeholder(placeholder)
            .when(self.read_only, |root| root.aria_description("Read only"))
            .when(self.invalid, |root| root.aria_description("Invalid value"))
            .when(!self.disabled, |root| {
                root.on_a11y_action(AccessibleAction::Focus, move |_, window, cx| {
                    a11y_focus.update(cx, |state, cx| state.focus(window, cx));
                })
            })
            .when(!self.disabled, |root| {
                root.on_mouse_down(MouseButton::Left, move |_, window, cx| {
                    click_state.update(cx, |state, cx| state.focus(window, cx));
                })
            })
            .when(!self.disabled && !self.read_only, |root| {
                root.on_a11y_action(AccessibleAction::SetValue, move |data, window, cx| {
                    if let Some(gpui_kit::accesskit::ActionData::Value(value)) = data {
                        action_state.update(cx, |state, cx| {
                            let end = state.value().encode_utf16().count();
                            state.replace_text_in_range(Some(0..end), value, window, cx);
                        });
                    }
                })
            })
            .flex()
            .w_full()
            .min_w_0()
            .px(theme.space(2.5))
            .text_color(theme.colors.foreground);
        let root = if self.bordered {
            focus::shown_for(
                control::frame(root, theme, self.invalid),
                theme,
                focused,
                self.invalid,
            )
            // The ring is a shadow painted under the whole box; a translucent
            // fill would show it across a tall textarea.
            .when_some(
                focused.then(|| theme.opaque(theme.control().background)),
                |root, fill| root.bg(fill),
            )
        } else {
            super::theme::primitives::text::sm(root, theme)
        };
        root.when(self.disabled, disabled::style)
            .when_some(paste_handler, |root, handler| {
                root.capture_action(move |_: &gpui_kit::base::input::Paste, window, cx| {
                    if let Some(clipboard) = cx.read_from_clipboard()
                        && handler(&clipboard, window, cx)
                    {
                        cx.stop_propagation();
                    }
                })
            })
            .child(state)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui_kit::{AppContext as _, Context, Render, TestAppContext, VisualTestContext};
    use std::{cell::Cell, rc::Rc};

    struct PasteProbe {
        input: Entity<InputState>,
        textarea: Entity<TextareaState>,
        multiline: bool,
        disabled: bool,
        read_only: bool,
        hits: Rc<Cell<usize>>,
    }

    impl Render for PasteProbe {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            let hits = self.hits.clone();
            let handler = move |item: &ClipboardItem, _: &mut Window, _: &mut App| {
                hits.set(hits.get() + 1);
                item.text().as_deref() == Some("asset")
            };
            if self.multiline {
                Textarea::new(&self.textarea)
                    .disabled(self.disabled)
                    .read_only(self.read_only)
                    .on_paste(handler)
                    .into_any_element()
            } else {
                Input::new(&self.input)
                    .disabled(self.disabled)
                    .read_only(self.read_only)
                    .on_paste(handler)
                    .into_any_element()
            }
        }
    }

    #[gpui_kit::test]
    fn paste_hooks_consume_payloads_and_respect_editability(cx: &mut TestAppContext) {
        cx.update(super::super::theme::init);
        for multiline in [false, true] {
            let hits = Rc::new(Cell::new(0));
            let (probe, visual) = cx.add_window_view({
                let hits = hits.clone();
                move |window, cx| PasteProbe {
                    input: cx.new(|cx| InputState::new(window, cx)),
                    textarea: cx.new(|cx| TextareaState::new(window, cx)),
                    multiline,
                    disabled: false,
                    read_only: false,
                    hits,
                }
            });
            let draw = |visual: &mut VisualTestContext| {
                visual.update(|window, cx| window.draw(cx).clear(cx));
            };
            let dispatch = |visual: &mut VisualTestContext, text: &str| {
                visual.update(|window, cx| {
                    if multiline {
                        let textarea = probe.read(cx).textarea.clone();
                        textarea.update(cx, |state, cx| state.focus(window, cx));
                    } else {
                        let input = probe.read(cx).input.clone();
                        input.update(cx, |state, cx| state.focus(window, cx));
                    }
                    cx.write_to_clipboard(ClipboardItem::new_string(text.into()));
                    window.dispatch_action(Box::new(gpui_kit::base::input::Paste), cx);
                });
            };
            let value = |visual: &mut VisualTestContext| {
                visual.update(|_, cx| {
                    let probe = probe.read(cx);
                    if multiline {
                        probe.textarea.read(cx).value().to_string()
                    } else {
                        probe.input.read(cx).value().to_string()
                    }
                })
            };

            draw(visual);
            dispatch(visual, "asset");
            assert_eq!(hits.get(), 1);
            assert_eq!(value(visual), "");

            dispatch(visual, "text");
            assert_eq!(hits.get(), 2);
            assert_eq!(value(visual), "text");

            for (disabled, read_only) in [(true, false), (false, true)] {
                probe.update(visual, |probe, cx| {
                    probe.disabled = disabled;
                    probe.read_only = read_only;
                    cx.notify();
                });
                draw(visual);
                dispatch(visual, "asset");
                assert_eq!(hits.get(), 2);
                assert_eq!(value(visual), "text");
            }
        }
    }
}

#[cfg(test)]
mod spelling_tests {
    use super::*;
    use gpui_kit::{AppContext as _, Render, TestAppContext, VisualTestContext};

    struct Notes {
        input: Entity<TextareaState>,
        misspellings: Entity<Misspellings>,
    }

    impl Render for Notes {
        fn render(&mut self, _: &mut Window, _: &mut gpui_kit::Context<Self>) -> impl IntoElement {
            gpui_kit::div().w(px(400.)).child(
                Textarea::new(&self.input)
                    .aria_label("Notes")
                    .misspellings(&self.misspellings),
            )
        }
    }

    fn notes(text: &'static str, cx: &mut TestAppContext) -> (Entity<Notes>, VisualTestContext) {
        cx.update(super::super::theme::init);
        let window = cx.add_window(move |window, cx| {
            let input = cx.new(|cx| TextareaState::new(window, cx));
            input.update(cx, |input, cx| input.set_value(text, window, cx));
            let misspellings = cx.new(|cx| Misspellings::new(&input, cx));
            Notes {
                input,
                misspellings,
            }
        });
        let view = window.root(cx).unwrap();
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.update(|window, cx| {
            window.activate_window();
            let input = view.read(cx).input.clone();
            input.update(cx, |input, cx| input.focus(window, cx));
            window.draw(cx).clear(cx);
        });
        (view, cx)
    }

    #[gpui_kit::test]
    fn edits_move_later_ranges_and_drop_touched_ones(cx: &mut TestAppContext) {
        let (view, mut cx) = notes("teh cat sat on teh mat", cx);
        let (input, misspellings) = cx.update(|_, cx| {
            let view = view.read(cx);
            (view.input.clone(), view.misspellings.clone())
        });
        cx.update(|_, cx| misspellings.update(cx, |m, cx| m.set([0..3, 15..18, 30..40], cx)));
        cx.update(|_, cx| {
            assert_eq!(
                misspellings.read(cx).ranges(),
                [0..3, 15..18],
                "out of range dropped"
            )
        });
        // Typing before the second word moves it.
        cx.update(|window, cx| {
            input.update(cx, |input, cx| {
                input.set_selected_range(4..4, cx);
                input.replace("big ", window, cx);
            })
        });
        cx.run_until_parked();
        cx.update(|_, cx| assert_eq!(misspellings.read(cx).ranges(), [0..3, 19..22]));
        // Typing inside the first word drops it.
        cx.update(|window, cx| {
            input.update(cx, |input, cx| {
                input.set_selected_range(1..1, cx);
                input.replace("x", window, cx);
            })
        });
        cx.run_until_parked();
        cx.update(|_, cx| {
            let misspellings = misspellings.read(cx);
            assert_eq!(misspellings.ranges(), vec![20..23]);
            assert_eq!(misspellings.range_at(21), Some(20..23));
            assert_eq!(misspellings.range_at(5), None);
        });
    }

    #[gpui_kit::test]
    fn a_suggestion_replaces_the_word_in_one_undoable_edit(cx: &mut TestAppContext) {
        let (view, mut cx) = notes("see teh cat", cx);
        let input = cx.update(|_, cx| view.read(cx).input.clone());
        cx.update(|_, cx| {
            view.read(cx)
                .misspellings
                .clone()
                .update(cx, |m, cx| m.set(std::iter::once(4..7), cx));
        });
        cx.dispatch_action(ReplaceMisspelling {
            range: 4..7,
            text: "the".into(),
        });
        cx.update(|_, cx| assert_eq!(input.read(cx).value(), "see the cat"));
        cx.simulate_keystrokes("secondary-z");
        cx.update(|_, cx| assert_eq!(input.read(cx).value(), "see teh cat"));
    }

    #[test]
    fn the_spelling_menu_puts_suggestions_above_the_edit_items() {
        let mut menu = SpellingMenu {
            range: 0..3,
            word: "teh".into(),
            menu: NativeMenu::new(),
        };
        menu.suggestion("the").suggestion("ten");
        let menu = edit_menu(menu.menu, false, true);
        assert!(!menu.is_empty());
    }
}

//! Nova field layout with explicit input state, label focus and validation messages.

use super::{
    input::{Input, InputState, Textarea},
    theme::UiTheme,
};
use gpui_kit::{
    AnyElement, App, ClickEvent, Div, ElementId, Entity, FocusHandle, FontWeight,
    InteractiveElement as _, IntoElement, MouseButton, ParentElement as _, RenderOnce, Role,
    SharedString, StatefulInteractiveElement as _, Styled, Window, div,
    prelude::FluentBuilder as _, px,
};
use std::rc::Rc;

/// What a click on a field's label does for controls that are not focused
/// by it, such as a checkbox toggling.
pub type FieldLabelClick = Rc<dyn Fn(&ClickEvent, &mut Window, &mut App)>;

/// A control that can receive a field's shared name, disabled and invalid state.
///
/// Text controls return their focus handle so a click on the label focuses
/// them. Controls without one focus target, such as a checkbox or a radio
/// group, return `None` from `field_label_focus` and may handle the click in
/// `field_label_click` instead.
pub trait FieldControl: 'static {
    /// Returns the control's real keyboard focus target.
    fn field_focus_handle(&self, cx: &App) -> FocusHandle {
        cx.focus_handle()
    }
    /// The handle a press on the label focuses; the control's focus handle
    /// unless overridden.
    fn field_label_focus(&self, cx: &App) -> Option<FocusHandle> {
        Some(self.field_focus_handle(cx))
    }
    /// What a click on the label does besides focusing; nothing by default.
    fn field_label_click(&self) -> Option<FieldLabelClick> {
        None
    }
    /// Whether the control sits before its label on one row, as a checkbox
    /// does; the description and error then line up under the label.
    fn field_inline(&self) -> bool {
        false
    }
    /// Applies the field state and erases the rendered control type.
    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement;
}

impl FieldControl for Input {
    fn field_focus_handle(&self, cx: &App) -> FocusHandle {
        Input::field_focus_handle(self, cx)
    }

    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement {
        self.aria_label(label)
            .disabled(disabled)
            .invalid(invalid)
            .into_any_element()
    }
}

impl FieldControl for Textarea {
    fn field_focus_handle(&self, cx: &App) -> FocusHandle {
        Textarea::field_focus_handle(self, cx)
    }

    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement {
        self.aria_label(label)
            .disabled(disabled)
            .invalid(invalid)
            .into_any_element()
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
/// The placement of a field label relative to its editor.
pub enum FieldOrientation {
    #[default]
    /// Place the label above the editor.
    Vertical,
    /// Place the label beside the editor.
    Horizontal,
}

#[derive(IntoElement)]
/// A labeled control with application-owned validation feedback.
pub struct Field<C: FieldControl = Input> {
    id: ElementId,
    control: C,
    label: SharedString,
    description: Option<SharedString>,
    error: Option<SharedString>,
    required: bool,
    disabled: bool,
    orientation: FieldOrientation,
    style: gpui_kit::StyleRefinement,
}
impl Field<Input> {
    /// Creates a field around the caller's retained editing state.
    pub fn new(id: impl Into<ElementId>, state: &Entity<InputState>) -> Self {
        Field::from_control(id, Input::new(state))
    }
}
impl<C: FieldControl> Field<C> {
    /// Creates a field around any supported text, choice or number control.
    pub fn from_control(id: impl Into<ElementId>, control: C) -> Self {
        Self {
            id: id.into(),
            control,
            label: SharedString::default(),
            description: None,
            error: None,
            required: false,
            disabled: false,
            orientation: FieldOrientation::Vertical,
            style: Default::default(),
        }
    }
    /// Sets the visible label and the control's accessible name.
    pub fn label(mut self, value: impl Into<SharedString>) -> Self {
        self.label = value.into();
        self
    }
    /// Sets supporting text below the editor.
    pub fn description(mut self, value: impl Into<SharedString>) -> Self {
        self.description = Some(value.into());
        self
    }
    /// Shows validation feedback and marks the editor invalid.
    pub fn error(mut self, value: impl Into<SharedString>) -> Self {
        self.error = Some(value.into());
        self
    }
    /// Marks the field as required in its visible and accessible label.
    pub fn required(mut self, value: bool) -> Self {
        self.required = value;
        self
    }
    /// Disables interaction and applies the disabled appearance.
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }
    /// Places the label above or beside the editor.
    pub fn orientation(mut self, value: FieldOrientation) -> Self {
        self.orientation = value;
        self
    }
}
impl<C: FieldControl> Styled for Field<C> {
    fn style(&mut self) -> &mut gpui_kit::StyleRefinement {
        &mut self.style
    }
}
impl<C: FieldControl> RenderOnce for Field<C> {
    fn render(self, _: &mut Window, cx: &mut App) -> impl IntoElement {
        let t = UiTheme::read(cx).clone();
        let focus = self.control.field_label_focus(cx);
        let click = self.control.field_label_click();
        let inline = self.control.field_inline();
        let label = if self.required {
            format!("{} (required)", self.label).into()
        } else {
            self.label.clone()
        };
        let interactive = !self.disabled && (focus.is_some() || click.is_some());
        let label_view = div()
            .id((self.id.clone(), "label"))
            .flex()
            .items_center()
            .gap(t.space(1.))
            .font_weight(FontWeight::MEDIUM)
            .text_size(t.text(14.))
            .line_height(t.text(20.))
            .child(self.label)
            .when(self.required, |label| label.child(" *"))
            .when(interactive, |label| label.cursor_pointer())
            .when(!self.disabled, |label| {
                label
                    .when_some(focus, |label, focus| {
                        label.on_mouse_down(MouseButton::Left, move |_, window, cx| {
                            focus.focus(window, cx)
                        })
                    })
                    .when_some(click, |label, click| {
                        label.on_click(move |event, window, cx| click(event, window, cx))
                    })
            });
        let description = self.error.clone().or(self.description.clone());
        let invalid = self.error.is_some();
        let description = description.map(|description| {
            div()
                .id("description")
                .when(invalid, |description| description.role(Role::Alert))
                .text_size(t.text(14.))
                .line_height(t.text(20.))
                .text_color(if invalid {
                    t.colors.destructive
                } else {
                    t.colors.muted_foreground
                })
                .child(description)
        });
        let control = self
            .control
            .into_field_control(label, self.disabled, invalid);
        let root = div()
            .id(self.id)
            .role(Role::Group)
            .w_full()
            .flex()
            .gap(t.space(2.))
            .font_family(t.fonts.body.clone())
            .text_color(t.colors.foreground);
        let root = if inline {
            // Checkbox first, then the label with its note beneath it.
            root.items_start().gap(t.space(3.)).child(control).child(
                div()
                    .flex_1()
                    .min_w_0()
                    .flex()
                    .flex_col()
                    .gap(t.space(1.5))
                    .child(label_view)
                    .children(description),
            )
        } else {
            root.when(self.orientation == FieldOrientation::Vertical, |root| {
                root.flex_col()
            })
            .when(self.orientation == FieldOrientation::Horizontal, |root| {
                root.items_center()
            })
            .child(label_view)
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .flex()
                    .flex_col()
                    .gap(t.space(1.5))
                    .child(control)
                    .children(description),
            )
        };
        super::theme::apply_style(root, &self.style)
    }
}

/// Stacks related fields with Nova spacing.
pub fn field_group(cx: &App) -> Div {
    div()
        .flex()
        .flex_col()
        .w_full()
        .gap(UiTheme::read(cx).space(7.))
}
/// Stacks a field editor and supporting content.
pub fn field_content(cx: &App) -> Div {
    div()
        .flex()
        .flex_col()
        .flex_1()
        .gap(UiTheme::read(cx).space(1.5))
}
/// Creates a themed field heading.
pub fn field_title(cx: &App) -> Div {
    let t = UiTheme::read(cx);
    div()
        .flex()
        .items_center()
        .gap(t.space(2.))
        .font_family(t.fonts.body.clone())
        .font_weight(FontWeight::MEDIUM)
        .text_size(t.text(14.))
        .line_height(t.text(20.))
        .text_color(t.colors.foreground)
}
/// Creates a horizontal divider between field sections.
pub fn field_separator(cx: &App) -> Div {
    div().w_full().h(px(1.)).bg(UiTheme::read(cx).colors.border)
}

#[cfg(test)]
mod choice_tests {
    use super::super::checkbox::Checkbox;
    use super::super::radio_group::{RadioGroup, RadioItem};
    use super::*;
    use gpui_kit::{
        Context, Entity, Render, TestAppContext, VisualTestContext, test::TestQueryExt as _,
    };

    struct Form {
        checked: bool,
    }

    impl Render for Form {
        fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            let view = cx.entity();
            div()
                .flex()
                .flex_col()
                .child(
                    Field::from_control(
                        "notify",
                        Checkbox::new("notify-box").checked(self.checked).on_change(
                            move |next, _, _, cx| {
                                view.update(cx, |form, cx| {
                                    form.checked = next;
                                    cx.notify()
                                })
                            },
                        ),
                    )
                    .label("Notify the channel")
                    .error("Pick at least one option."),
                )
                .child(
                    Field::from_control(
                        "size",
                        RadioGroup::new("size-group")
                            .item(RadioItem::new("s", "s").label("Small"))
                            .item(RadioItem::new("l", "l").label("Large")),
                    )
                    .label("Size")
                    .description("Applies to new posts."),
                )
        }
    }

    #[gpui_kit::test]
    fn checkboxes_and_radio_groups_take_the_field_label_and_note(cx: &mut TestAppContext) {
        cx.update(super::super::theme::init);
        let window = cx.add_window(|_, _| Form { checked: false });
        let view: Entity<Form> = window.root(cx).unwrap();
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        let checkbox = cx.update(|window, _| {
            window.find_by_label("Small");
            window.find_by_label("Notify the channel")
        });
        let bounds = checkbox.bounds();
        // The label sits on the checkbox's row, after it.
        let on_label = gpui_kit::point(bounds.right() + px(40.), bounds.center().y);
        cx.simulate_click(on_label, gpui_kit::Modifiers::default());
        cx.update(|_, cx| {
            assert!(
                view.read(cx).checked,
                "a click on the label toggles the box"
            )
        });
    }
}

//! Nova radio selection with GPUI Kit controls and roving focus.
use super::theme::{
    RovingFocus, UiTheme, apply_style,
    primitives::{control, disabled, focus, text},
};
use gpui_kit::{
    App, ElementId, InteractiveElement as _, IntoElement, ParentElement as _, RenderOnce,
    SharedString, StatefulInteractiveElement as _, StyleRefinement, Styled, Window, div,
    prelude::FluentBuilder as _,
};
use std::rc::Rc;

type ChangeHandler = Rc<dyn Fn(SharedString, &mut Window, &mut App)>;
/// One radio option with a stable ID and selected value.
pub struct RadioItem {
    id: ElementId,
    value: SharedString,
    label: SharedString,
    disabled: bool,
    style: StyleRefinement,
}
impl RadioItem {
    /// Creates a `RadioItem` with a stable caller-owned ID.
    pub fn new(id: impl Into<ElementId>, value: impl Into<SharedString>) -> Self {
        let value = value.into();
        Self {
            id: id.into(),
            label: value.clone(),
            value,
            disabled: false,
            style: Default::default(),
        }
    }
    /// Disables interaction and applies the disabled appearance.
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }
    /// Sets the visible label.
    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = label.into();
        self
    }
}
impl Styled for RadioItem {
    fn style(&mut self) -> &mut StyleRefinement {
        &mut self.style
    }
}
#[derive(IntoElement)]
/// A controlled, single-choice group with roving keyboard focus.
pub struct RadioGroup {
    id: ElementId,
    value: Option<SharedString>,
    label: Option<SharedString>,
    disabled: bool,
    items: Vec<RadioItem>,
    on_change: Option<ChangeHandler>,
    style: StyleRefinement,
}
impl RadioGroup {
    /// Creates a `RadioGroup` with a stable caller-owned ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            value: None,
            label: None,
            disabled: false,
            items: Vec::new(),
            on_change: None,
            style: Default::default(),
        }
    }
    /// Sets the caller-owned value displayed by this control.
    pub fn value(mut self, value: impl Into<SharedString>) -> Self {
        self.value = Some(value.into());
        self
    }
    /// Sets the accessible name of the control.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = Some(label.into());
        self
    }
    /// Disables interaction and applies the disabled appearance.
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }
    /// Appends an option to the group.
    pub fn item(mut self, item: RadioItem) -> Self {
        self.items.push(item);
        self
    }
    /// Reports a requested value change; retain the next value in the owning view.
    pub fn on_change(
        mut self,
        handler: impl Fn(SharedString, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_change = Some(Rc::new(handler));
        self
    }
}
impl Styled for RadioGroup {
    fn style(&mut self) -> &mut StyleRefinement {
        &mut self.style
    }
}
impl RenderOnce for RadioGroup {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let colors = theme.colors;
        let selected = self
            .items
            .iter()
            .position(|i| Some(&i.value) == self.value.as_ref());
        let focus = RovingFocus::new(
            self.id.clone(),
            &self
                .items
                .iter()
                .map(|i| (i.id.clone(), self.disabled || i.disabled))
                .collect::<Vec<_>>(),
            selected,
            window,
            cx,
        );
        let values: Vec<_> = self.items.iter().map(|i| i.value.clone()).collect();
        let count = self.items.len();
        let children = self
            .items
            .into_iter()
            .enumerate()
            .map(|(index, item)| {
                let checked = Some(index) == selected;
                let disabled = self.disabled || item.disabled;
                let handle = focus.handles[index].as_ref();
                let focused = handle.is_some_and(|h| h.is_focused(window));
                let change = self.on_change.clone();
                let circle =
                    focus::shown(control::radio_dot(div(), &theme, checked), &theme, focused);
                let radio = gpui_kit::base::Radio::new(item.id)
                    .checked(checked)
                    .disabled(disabled)
                    .accessibility_label(item.label.clone())
                    .set_position(index + 1, count)
                    .when_some(handle, |radio, h| radio.track_focus(h).tab_stop(h.tab_stop))
                    .flex()
                    .items_center()
                    .gap(theme.space(2.))
                    .text_color(colors.foreground)
                    .child(circle)
                    .child(gpui_kit::Text::new_inaccessible(item.label))
                    .when_some(change, |radio, handler| {
                        radio.on_change(move |_, _, window, cx| {
                            handler(item.value.clone(), window, cx)
                        })
                    });
                let radio = disabled::interactive(text::sm(radio, &theme), disabled);
                apply_style(radio, &item.style)
            })
            .collect::<Vec<_>>();
        let on_change = self.on_change;
        let root = gpui_kit::base::RadioGroup::new(self.id)
            .flex()
            .flex_col()
            .gap(theme.space(2.))
            .when_some(self.label, |root, label| root.aria_label(label))
            .on_key_down(move |event, window, cx| {
                if let Some(index) = focus.key(event, None, window, cx)
                    && let Some(change) = &on_change
                {
                    change(values[index].clone(), window, cx);
                }
            })
            .children(children);
        apply_style(root, &self.style)
    }
}

impl super::field::FieldControl for RadioGroup {
    fn field_label_focus(&self, _: &App) -> Option<gpui_kit::FocusHandle> {
        None
    }

    fn into_field_control(
        self,
        label: SharedString,
        disabled: bool,
        _invalid: bool,
    ) -> gpui_kit::AnyElement {
        let disabled = self.disabled || disabled;
        self.aria_label(label).disabled(disabled).into_any_element()
    }
}
